// Deterministic randomness.
// Reducers stay pure: any action that needs randomness carries a `seed`,
// generated by the action creator. Replaying the same actions therefore
// always produces the same game, which is what a networked match needs.

export const newSeed = () => Math.floor(Math.random() * 2 ** 32);

/** mulberry32 PRNG – small, fast and good enough for shuffling cards. */
export function createRng(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Fisher–Yates shuffle, returns a new array. */
export function shuffle(items, seed) {
  const rng = createRng(seed);
  const result = [...items];
  for (let i = result.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}
